<?php require_once '../config/auth.php';require_admin();$action=$_POST['action']??$_GET['action']??'';try{if($action==='create'||$action==='update'){$code=trim($_POST['code']);$name=trim($_POST['name']);$cat=$_POST['category_id']!==''?(int)$_POST['category_id']:null;$price=(float)$_POST['price'];$stock=(int)$_POST['stock'];$img=trim($_POST['image_url']??'');if($action==='create'){$s=$pdo->prepare('INSERT INTO products(code,name,category_id,price,stock,image_url) VALUES(?,?,?,?,?,?)');$s->execute([$code,$name,$cat,$price,$stock,$img]);}else{$s=$pdo->prepare('UPDATE products SET code=?,name=?,category_id=?,price=?,stock=?,image_url=? WHERE id=?');$s->execute([$code,$name,$cat,$price,$stock,$img,(int)$_POST['id']]);}}elseif($action==='delete'){$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([(int)$_GET['id']]);}header('Location: ../produk.php');}catch(Throwable $e){http_response_code(400);echo 'Gagal: '.e($e->getMessage()).' <br><a href="../produk.php">Kembali</a>';}
